module tb;
bit clk=0;always #5 clk=~clk;bit rst=1;integer cycle=-1;
bit [7:0] s_axis_tdata=0;bit [0:0] s_axis_tvalid=0,s_axis_tlast=0,s_axis_tkeep='1;
wire [0:0] s_axis_tready;bit [7:0] s_axis_tid=0;
bit [7:0] s_axis_tdest=0;bit [0:0] s_axis_tuser=0;
